}

fn cents(s: Str) -> Option<Int> {
  let p = s.split(".");
  if p.len() > 2 { return None; }
  if !digs(p[0]) { return None; }
  let w = p[0].parse_int()?;
  if p.len() == 1 { return Some(w * 100); }
  if !digs(p[1]) || p[1].len() > 2 { return None; }
  let f = p[1].parse_int()?;
  if p[1].len() == 1 { Some(w * 100 + f * 10) } else { Some(w * 100 + f) }
}

fn date_ok(s: Str) -> Bool {
  let b = s.to_bytes();
  if b.len() != 10 { return false; }
  for i in 0..10 {
    if i == 4 || i == 7 { if b[i] != 45 { return false; } }
    else if b[i] < 48 || b[i] > 57 { return false; }
  }
  let m = (b[5] - 48) * 10 + b[6] - 48;
  let d = (b[8] - 48) * 10 + b[9] - 48;
  m >= 1 && m <= 12 && d >= 1 && d <= 31
}

