fn check(line: Str) -> Str {
  let raw = line.split(",");
  if raw.len() != 5 { return "expected 5 fields, got " + raw.len().to_str(); }
  let f = raw.map(|x| x.trim());
  if f[0] == "" { return "empty order_id"; }
  if f[1] == "" { return "empty customer_id"; }
  let d = f[2];
  let mut ok = d.len() == 10 && d.slice(4, 5) == "-" && d.slice(7, 8) == "-" && digits(d.slice(0, 4)) && digits(d.slice(5, 7)) && digits(d.slice(8, 10));
  if !ok { return "invalid order_date"; }
  let m = d.slice(5, 7).parse_int().unwrap_or(0);
  let dd = d.slice(8, 10).parse_int().unwrap_or(0);
  if m < 1 || m > 12 || dd < 1 || dd > 31 { return "invalid order_date"; }
  let p = f[3].split(".");
  ok = (p.len() == 1 && digits(p[0])) || (p.len() == 2 && digits(p[0]) && digits(p[1]) && p[1].len() <= 2);
  if !ok { return "invalid amount"; }
  if f[4] != "paid" && f[4] != "pending" && f[4] != "refunded" { return "invalid status"; }
  ""
}

