fn dig(c: Int) -> Bool { c >= 48 && c <= 57 }
fn alpha(c: Int) -> Bool { (c >= 65 && c <= 90) || (c >= 97 && c <= 122) }

fn valid(b: Bytes) -> Bool {
  if b.len() < 21 { return false; }
  for i in 0..20 {
    let c = b[i];
    let ok = if i == 4 || i == 7 { c == 45 } else if i == 10 { c == 84 } else if i == 13 || i == 16 { c == 58 } else if i == 19 { c == 90 } else { dig(c) };
    if !ok { return false; }
  }
  b[20] == 32
}

