    let b = line.to_bytes();
    if !valid(b) { continue; }
    let mut j = 21;
    while j < b.len() && alpha(b[j]) { j += 1; }
    if b.slice(21, j).to_str().to_lowercase() != "error" { continue; }
    let day = line.slice(0, 10);
    counts.insert(day, counts.get(day).unwrap_or(0) + 1);
