fn amount(s: Str) -> Option<Str> {
  let p = s.split(".");
  if p.len() == 1 && digits(p[0]) { return Some(p[0] + ".00"); }
  if p.len() == 2 && digits(p[0]) && digits(p[1]) && p[1].len() <= 2 {
    return Some(p[0] + "." + (if p[1].len() == 1 { p[1] + "0" } else { p[1] }));
  }
  None
}

