  if !digits(p[0]) || !digits(p[1]) || !digits(p[2]) { return false; }
  let m = p[1].parse_int().unwrap_or(0);
  let d = p[2].parse_int().unwrap_or(0);
  m >= 1 && m <= 12 && d >= 1 && d <= 31
}

fn parse(line: Str) -> Option<Row> {
  let raw = line.split(",");
  if raw.len() != 5 { return None; }
  let f = raw.map(|x| x.trim());
  if f[0] == "" || f[1] == "" { return None; }
  if !date_ok(f[2]) { return None; }
  let a = amount(f[3])?;
  if f[4] != "paid" && f[4] != "pending" && f[4] != "refunded" { return None; }
  Some(Row { id: f[0], line: f[0] + "," + f[1] + "," + f[2] + "," + a + "," + f[4] })
}

