  if !digits(y) || !digits(m) || !digits(d) { return false; }
  let mi = m.parse_int().unwrap_or(0);
  let di = d.parse_int().unwrap_or(0);
  mi >= 1 && mi <= 12 && di >= 1 && di <= 31
}

fn cents(s: Str) -> Option<Int> {
  let p = s.split(".");
  if p.len() == 1 {
    if !digits(p[0]) { return None; }
    return Some(p[0].parse_int()? * 100);
  }
  if p.len() != 2 { return None; }
  if !digits(p[0]) || !digits(p[1]) || p[1].len() > 2 { return None; }
  let f = p[1].parse_int()?;
  Some(p[0].parse_int()? * 100 + (if p[1].len() == 1 { f * 10 } else { f }))
}

fn money(c: Int) -> Str {
  let r = c % 100;
  (c / 100).to_str() + "." + (if r < 10 { "0" } else { "" }) + r.to_str()
}

fn main(input: Dir, out: Dir, api: Http) -> Result<Str, Failed> {
  let body = api.get("/v1/rates?base=USD").map_err(|e| Failed::Http(e))?.to_str();
  let doc = body.parse_json().map_err(|e| Failed::Bad(e))?;
  let Some(rate) = doc.get("rates").and_then(|r| r.get("EUR")).and_then(|v| v.as_float()) else {
    return Err(Failed::Bad("no EUR rate"));
  };
  let text = input.read("orders.csv").map_err(|e| Failed::Io(e))?.to_str();
  let lines = text.lines();
  let mut seen: Map<Str, Int> = Map::new();
  let mut tot: Map<Str, Int> = Map::new();
  let mut first = true;
  for line in lines {
    if line.trim() == "" { continue; }
    if first { first = false; continue; }
    let f = line.split(",");
    if f.len() != 5 { continue; }
    let id = f[0].trim(); let cu = f[1].trim();
    let st = f[4].trim();
    if id == "" || cu == "" || !date_ok(f[2].trim()) { continue; }
    let Some(c) = cents(f[3].trim()) else { continue; };
    if st != "paid" && st != "pending" && st != "refunded" { continue; }
    if seen.get(id).is_some() { continue; }
    seen.insert(id, 1);
    if st == "paid" { tot.insert(cu, tot.get(cu).unwrap_or(0) + c); }
  }
  let mut rows: List<Str> = ["customer_id,total_eur"];
  for k in tot.keys() {
    let e = (tot.get(k).unwrap_or(0).to_float() * rate).round().to_int().unwrap_or(0);
    rows.push(k + "," + money(e));
  }
  out.write("totals_eur.csv", (rows.join("\n") + "\n").to_bytes()).map_err(|e| Failed::Io(e))?;
  Ok("rate " + rate.to_str() + "\n" + rows.join("\n"))
}
